-- V1: Identity and organization access (Figure 2, block A)
-- IDs are UUID v7 (time-ordered), generated by PostgreSQL 18.

CREATE TABLE users (
    id             UUID         PRIMARY KEY DEFAULT uuidv7(),
    email          VARCHAR(255) NOT NULL,
    password_hash  VARCHAR(255) NOT NULL,
    account_type   VARCHAR(30)  NOT NULL,
    email_verified BOOLEAN      NOT NULL DEFAULT FALSE,
    status         VARCHAR(20)  NOT NULL DEFAULT 'ACTIVE',

    CONSTRAINT uk_users_email UNIQUE (email),
    CONSTRAINT ck_users_account_type
        CHECK (account_type IN ('UPRM_MEMBER', 'EXTERNAL_ORGANIZATION')),
    CONSTRAINT ck_users_status
        CHECK (status IN ('ACTIVE', 'SUSPENDED'))
);

CREATE TABLE organizations (
    id              UUID         PRIMARY KEY DEFAULT uuidv7(),
    name            VARCHAR(255) NOT NULL,
    org_type        VARCHAR(30)  NOT NULL,
    approval_status VARCHAR(20)  NOT NULL DEFAULT 'PENDING',

    CONSTRAINT ck_organizations_org_type
        CHECK (org_type IN ('UPRM_OFFICE', 'UPRM_DEPARTMENT', 'EXTERNAL_COMPANY')),
    CONSTRAINT ck_organizations_approval_status
        CHECK (approval_status IN ('PENDING', 'APPROVED', 'REJECTED'))
);

CREATE TABLE role_assignments (
    id              UUID        PRIMARY KEY DEFAULT uuidv7(),
    user_id         UUID        NOT NULL REFERENCES users (id),
    role            VARCHAR(20) NOT NULL,
    organization_id UUID        REFERENCES organizations (id),

    CONSTRAINT ck_role_assignments_role
        CHECK (role IN ('STUDENT', 'INSTITUTIONAL', 'MODERATOR', 'COMPANY')),
    CONSTRAINT uk_role_assignments
        UNIQUE NULLS NOT DISTINCT (user_id, role, organization_id)
);

CREATE TABLE email_codes (
    id         UUID         PRIMARY KEY DEFAULT uuidv7(),
    user_id    UUID         NOT NULL REFERENCES users (id),
    code_hash  VARCHAR(255) NOT NULL,
    expires_at TIMESTAMPTZ  NOT NULL
);